    const cellsOf = block.rows.map((index) => reviewTableCells(lines[index]));
    if (cellsOf[0][0] !== 'Claim' && !cellsOf.some((cells) => /claim_[0-9a-f]{32}/.test(cells[0] || ''))) continue;
    block.rows.forEach((index, i) => {
      const cells = cellsOf[i], first = cells[0] || '', line = index + 1;
      const named = first.match(/claim_[0-9a-f]{32}/)?.[0] || null;
      if (named && first !== named) return report(line, named, 'non-bare-first-cell', 'first cell is not a bare claim ID, so the applier skips this row');
      if (named) claimRows++;
      if (cells.length !== 5) return report(line, named, 'wrong-cell-count', LINT_MESSAGES['wrong-cell-count'](cells));
      if (!named) return;
      const row = rowsById.get(named);
      if (!row) return report(line, named, 'unknown-claim', 'claim is not in any given shard');
      let expected = row;
      if (row.targetOwner && row.targetUnitDigest === undefined) {
        if (!targetDigestOf) return report(line, named, 'target-digest-unverifiable', 'shard row has no recorded target digest; pass --inventory to resolve it');
        expected = { ...row, targetUnitDigest: targetDigestOf(row) };
      }
      for (const reason of ordinaryVerdictCellProblems(cells, expected, { checkNote: false, verdicts: REVIEW_VERDICTS })) report(line, named, reason, LINT_MESSAGES[reason](cells));
    });
  }
  return { ok: problems.length === 0, claimRows, problems };
}

function indexVerdicts(verdicts, expectedIds) {
  const index = new Map();
  for (const row of verdicts) {
    if (index.has(row.claimId)) throw new Error(`duplicate verdict ${row.claimId}`);
    if (!expectedIds.has(row.claimId)) throw new Error(`unknown verdict ${row.claimId}`);
    if (!REVIEW_VERDICTS.includes(row.verdict) || !row.note?.trim()) throw new Error(`verdict and own note required for ${row.claimId}`);
    index.set(row.claimId, row);
  }
  for (const id of expectedIds) if (!index.has(id)) throw new Error(`missing verdict ${id}`);
  return index;
}

export function scoreReviewPack(key, verdicts) {
  if (key.rows.length !== 30 || key.rows.filter((row) => row.mutated).length !== 6) throw new Error('invalid sensitivity key: expected 6 mutations and 24 controls');
  const index = indexVerdicts(verdicts, new Set(key.rows.map((row) => row.claimId)));
  const caught = key.rows.filter((row) => row.mutated && index.get(row.claimId).verdict !== 'ok').length;
  const falseFlags = key.rows.filter((row) => !row.mutated && index.get(row.claimId).verdict !== 'ok').length;
  const scoredVerdicts = [...index.values()].sort((a, b) => a.claimId.localeCompare(b.claimId));
  return { caught, mutations: 6, falseFlags, controls: 24, pass: caught >= 5 && falseFlags <= 2, reviewer: key.reviewer, commit: key.commit, packId: key.packId, scoreId: jsonDigest({ key, verdicts: scoredVerdicts }) };
}

export function parseReviewVerdicts(text, reviewer, binding = null) {
  const header = text.match(/^Reviewer:\s*(.+)$/im)?.[1]?.trim();
  if (header !== reviewer) throw new Error('reviewer header must equal --reviewer');
  if (binding) for (const [headerName, expected] of [['Pack commit', binding.commit], ['Pack id', binding.packId], ['Seed score', binding.scoreId]]) {
    const actual = text.match(new RegExp(`^${headerName}:\\s*(.+)$`, 'im'))?.[1]?.trim();
    if (actual !== expected) throw new Error(`review report ${headerName} does not match the shown pack or scored sensitivity result`);
  }
  const ordinary = /^Review mode:\s*ordinary\s*$/im.test(text);
  const verdicts = [];
  for (const line of text.split(/\r?\n/)) {
    if (!/^\s*\|\s*claim_[0-9a-f]{32}\s*\|/.test(line)) continue;
    const cells = line.trim().split(/(?<!\\)\|/).slice(1, -1).map((cell) => cell.trim().replace(/\\\|/g, '|'));
    if (cells.length !== (ordinary ? 5 : 3) || !REVIEW_VERDICTS.includes(cells[1]) || !cells[2]) throw new Error('verdict row requires claimId, verdict, own note and ordinary shown digests');
    verdicts.push({ claimId: cells[0], verdict: cells[1], note: cells[2], ...(ordinary ? { sourceUnitDigest: cells[3], targetUnitDigest: cells[4] === 'none' ? null : cells[4] } : {}) });
  }
  if (!verdicts.length) throw new Error('review report has no verdict rows');
  return verdicts;
}

export function applyReviewVerdicts(context, shard, { verdicts, reviewer, reportPath, pack, seedProof, ordinaryReview = false, reviewedAt = new Date().toISOString().slice(0, 10) }) {
  requireVerifiedShard(context, shard);
  if (ordinaryReview && isCheckpointReviewReport(reportPath)) throw new Error('checkpoint reviews require sensitivity proof and pack binding');
  if (ordinaryReview && !context.repoRoot) throw new Error('ordinary review requires a repository with committed report evidence');
  const legacy = isLegacyDecisionShard(shard);
  const author = shard.authorSession || (legacy ? pack?.authorSession || reviewReportAuthor(buildCommittedReviewReportLookup(context.repoRoot, context.inventory.commit)(reportPath)) : null);
